package e.e.a;
import android.preference.*;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;
public final class SettingsTools {
 static PreferenceGroup parent(PreferenceGroup g,Preference p){for(int i=0;i<g.getPreferenceCount();i++){Preference x=g.getPreference(i);if(x==p)return g;if(x instanceof PreferenceGroup){PreferenceGroup r=parent((PreferenceGroup)x,p);if(r!=null)return r;}}return null;}
 // Run after all preference installers so the preview replaces legacy entries.
 static void finishSettings(PreferenceActivity a){SettingsPlacement233.finish(a);Preference player=a.findPreference("player");PreferenceGroup group=player instanceof PreferenceGroup?(PreferenceGroup)player:a.getPreferenceScreen();visibilityEntry(a,group);PlayerVisibility192.settings(a,group);PlayerButtons192.settings(a,group);CommentSettings192.settings(a);detailButtons(a);cleanSummaries(a.getPreferenceScreen());}
 static String withoutFinalStop(CharSequence text){if(text==null)return null;String value=text.toString().trim();while(value.endsWith("。")||value.endsWith("."))value=value.substring(0,value.length()-1).trim();return value;}
 static void cleanSummaries(PreferenceGroup group){if(group==null)return;for(int n=0;n<group.getPreferenceCount();n++){Preference p=group.getPreference(n);CharSequence summary=p.getSummary();if(summary!=null){String clean=withoutFinalStop(summary);if(!clean.contentEquals(summary))p.setSummary(clean);}if(p instanceof PreferenceGroup)cleanSummaries((PreferenceGroup)p);}}
 static void visibilityEntry(PreferenceActivity a,PreferenceGroup group){String key="player_controls_visibility_mode";Preference prior=a.findPreference(key);if(prior instanceof VisibilityPreference)return;PreferenceGroup container=prior==null?group:parent(a.getPreferenceScreen(),prior);int order=prior==null?group.getPreferenceCount():prior.getOrder();if(prior!=null&&container!=null)container.removePreference(prior);VisibilityPreference entry=new VisibilityPreference(a);entry.setKey(key);entry.setOrder(order);(container==null?group:container).addPreference(entry);}
 static final class VisibilityPreference extends Preference {VisibilityPreference(android.content.Context c){super(c);}public void setSummary(CharSequence current){String label=withoutFinalStop(current);String help=PanelUi.tr(getContext(),"操作ボタンとシークバーを常時表示する再生モードを選択します","Choose the playback modes in which controls and the seek bar stay visible","選擇持續顯示操作按鈕和進度條的播放模式");String separator=UiStrings.translate("操作部の常時表示").equals("操作部の常時表示")?"：":": ";super.setSummary(label==null||label.isEmpty()?help:label.contains(help)?label:label+separator+help);}}
 static final class SummarySync implements android.content.SharedPreferences.OnSharedPreferenceChangeListener,View.OnAttachStateChangeListener,Runnable {final java.lang.ref.WeakReference<PreferenceActivity> activity;final java.lang.ref.WeakReference<View> view;final android.content.SharedPreferences prefs;boolean active,pending;SummarySync(PreferenceActivity a,View v){activity=new java.lang.ref.WeakReference<>(a);view=new java.lang.ref.WeakReference<>(v);prefs=PreferenceManager.getDefaultSharedPreferences(a);}public void onViewAttachedToWindow(View v){if(!active){active=true;prefs.registerOnSharedPreferenceChangeListener(this);}}public void onViewDetachedFromWindow(View v){active=false;prefs.unregisterOnSharedPreferenceChangeListener(this);v.removeCallbacks(this);pending=false;}public void onSharedPreferenceChanged(android.content.SharedPreferences p,String key){View v=view.get();if(active&&!pending&&v!=null){pending=true;v.post(this);}}public void run(){pending=false;PreferenceActivity a=activity.get();if(active&&a!=null&&!a.isFinishing()&&!a.isDestroyed())cleanSummaries(a.getPreferenceScreen());}}
 static void detailButtons(PreferenceActivity a){PreferenceGroup root=a.getPreferenceScreen();if(root==null)return;String key="video_info_follow_button";Preference existing=a.findPreference(key);if(existing!=null&&!(existing instanceof CheckBoxPreference))return;PreferenceGroup target=existing==null?null:parent(root,existing);if(target==null){Preference other=a.findPreference("nicoid_content_filter");target=other instanceof PreferenceGroup?(PreferenceGroup)other:root;}int order=existing==null?target.getPreferenceCount():existing.getOrder();for(String oldKey:new String[]{key,"video_info_like_button","video_info_nicoad_button"}){Preference old=a.findPreference(oldKey);PreferenceGroup group=old==null?null:parent(root,old);if(group!=null)group.removePreference(old);}Preference entry=new Preference(a);entry.setKey(key);entry.setOrder(order);entry.setTitle(UiStrings.translate("動画情報欄のボタン"));entry.setSummary(PanelUi.tr(a,"動画情報に表示する「フォロー」「いいね」「ニコニ広告」のボタンを選択します","Choose which Follow, Like and NicoNico Ads buttons appear in video details","選擇影片資訊中顯示的追蹤、喜歡及 Niconico 廣告按鈕"));entry.setOnPreferenceClickListener(p->{DetailActions195.show(a);return true;});target.addPreference(entry);}
 public static void install(PreferenceActivity a){a.getListView().post(()->{if(a.isFinishing())return;PreferenceGroup root=a.getPreferenceScreen(),other=(PreferenceGroup)a.findPreference("nicoid_content_filter");if(other!=null){other.setTitle(PanelUi.tr(a,"その他","Other","其他"));NgCommentSettings.install(a,other);for(String key:new String[]{"search_suggestions_enabled","show_shorts_menu","video_info_follow_button"}){Preference p=a.findPreference(key);if(p!=null){PreferenceGroup old=parent(root,p);if(old!=null&&old!=other){old.removePreference(p);p.setOrder(other.getPreferenceCount());other.addPreference(p);}}}arrangeOther(root,other);}finishSettings(a);SettingsIntegrity.stripSummaries(a);ListView list=a.getListView();if(list.findViewWithTag("settings_search")!=null)return;SummarySync sync=new SummarySync(a,list);list.addOnAttachStateChangeListener(sync);if(list.isAttachedToWindow())sync.onViewAttachedToWindow(list);LinearLayout header=new LinearLayout(a);header.setTag("settings_search");header.setPadding(PanelUi.dp(a,16),PanelUi.dp(a,8),PanelUi.dp(a,16),PanelUi.dp(a,8));LinearLayout pill=new LinearLayout(a);pill.setGravity(android.view.Gravity.CENTER_VERTICAL);pill.setPadding(PanelUi.dp(a,14),0,PanelUi.dp(a,8),0);pill.setBackground(PanelUi.round(a,ThemeChoice.isNight(a)?0xff303238:0xffeeeeee,28));header.addView(pill,new LinearLayout.LayoutParams(-1,PanelUi.dp(a,48)));View icon=new SearchIcon(a);pill.addView(icon,new LinearLayout.LayoutParams(PanelUi.dp(a,24),PanelUi.dp(a,24)));EditText search=new EditText(a);search.setSingleLine(true);search.setHint(PanelUi.tr(a,"設定項目を検索","Search settings","搜尋設定項目"));search.setTextColor(PanelUi.ink(a));search.setHintTextColor(ThemeChoice.isNight(a)?0xffbfc1c6:0xff67696d);search.setBackground(null);search.setPadding(PanelUi.dp(a,12),0,PanelUi.dp(a,8),0);search.setInputType(android.text.InputType.TYPE_CLASS_TEXT);pill.addView(search,new LinearLayout.LayoutParams(0,-1,1));list.setItemsCanFocus(true);list.addHeaderView(header,null,false);Node snapshot=new Node(root);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int before,int count){snapshot.restore(s.toString().trim().toLowerCase(Locale.ROOT),false);}public void afterTextChanged(Editable e){}});});}
 static void arrangeOther(PreferenceGroup root,PreferenceGroup other){Preference ng=root.findPreference("nicoid_ng_comments"),filter=other.findPreference("nicoid_filter_list");if(ng==null)return;PreferenceGroup old=parent(root,ng);if(old!=null&&old!=other)old.removePreference(ng);if(old!=other)other.addPreference(ng);ArrayList<Preference> rest=new ArrayList<>();for(int n=0;n<other.getPreferenceCount();n++){Preference item=other.getPreference(n);if(item!=filter&&item!=ng)rest.add(item);}if(filter!=null)filter.setOrder(0);ng.setOrder(1);for(int n=0;n<rest.size();n++)rest.get(n).setOrder(n+2);}
 static final class SearchIcon extends View {final android.graphics.Paint p=new android.graphics.Paint(3);SearchIcon(android.content.Context c){super(c);setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);}protected void onDraw(android.graphics.Canvas c){c.save();float scale=Math.min(getWidth(),getHeight())/24f;c.scale(scale,scale);p.setColor(ThemeChoice.accent(getContext()));p.setStyle(android.graphics.Paint.Style.STROKE);p.setStrokeWidth(2);p.setStrokeCap(android.graphics.Paint.Cap.ROUND);c.drawCircle(10,10,6,p);c.drawLine(15,15,21,21,p);c.restore();}}
 static final class Node {final PreferenceGroup group;final ArrayList<Preference> entries=new ArrayList<>();final Map<Preference,Node> children=new HashMap<>();Node(PreferenceGroup g){group=g;for(int i=0;i<g.getPreferenceCount();i++){Preference p=g.getPreference(i);entries.add(p);if(p instanceof PreferenceGroup)children.put(p,new Node((PreferenceGroup)p));}}boolean restore(String q,boolean include){group.removeAll();for(Preference p:entries){boolean match=include||q.isEmpty()||String.valueOf(p.getTitle()).toLowerCase(Locale.ROOT).contains(q)||String.valueOf(p.getSummary()).toLowerCase(Locale.ROOT).contains(q);Node n=children.get(p);if(n!=null){if(n.restore(q,match))group.addPreference(p);}else if(match)group.addPreference(p);}return group.getPreferenceCount()>0;}}
}
